# features/steps/login_steps.py
from behave import given, when, then

@given('the user is on the login page')
def step_user_on_login_page(context):
    context.browser.get(context.base_url + '/login')

@when('the user enters valid credentials')
def step_enter_valid_credentials(context):
    context.browser.find_element_by_id('username').send_keys('admin')
    context.browser.find_element_by_id('password').send_keys('secret')
    context.browser.find_element_by_id('submit').click()

@when('the user enters invalid credentials')
def step_enter_invalid_credentials(context):
    context.browser.find_element_by_id('username').send_keys('wrong')
    context.browser.find_element_by_id('password').send_keys('wrong')
    context.browser.find_element_by_id('submit').click()

@then('the user is redirected to the dashboard')
def step_redirected_to_dashboard(context):
    assert '/dashboard' in context.browser.current_url

@then('an error message is displayed')
def step_error_message_displayed(context):
    error = context.browser.find_element_by_class_name('error-message')
    assert error.is_displayed()

